entries[211486] = { ["name"] = "Winding Slitherdrake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a dragonriding mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"These drakes feel at home in the depths of the earth and the far reaches of the sky.\"\nAchievement:\nA Serpentine Discovery" }
