entries[211495] = { ["name"] = "Dreambound Augment Rune", ["text"] = "Binds when picked up\nUse: Increases Agility, Intellect and Strength by 87 for 1 hour. Augment Rune. (1 Min Cooldown)\nRequires Renown Rank 18 with the Dream Wardens.\n\"The strength of the Dream condensed into an empowering mist.\"\nSell Price:" }
