entries[211515] = { ["name"] = "Splintered Spark of Awakening", ["text"] = "Dragonflight Season 4\nBinds when picked up\nUse: Combine 2 Splintered Spark of Awakening to create a Spark of Awakening.\nCrafting Reagent\n\"A fragment of a Spark of Awakening, its powers can be reformed if the pieces are gathered.\"\nSell Price:" }
