entries[212449] = { ["name"] = "Sikran's Endless Arsenal", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+1,914 [Agility or Strength]\nEquip: Assume a martial stance based on the last weapon drawn.\nUse: Surekian Flourish\nConjure dual swords from the Arsenal to rend your target, dealing ( 1 * 705278 ) Shadow damage over 3 sec. Gain 338 Parry and 225 Avoidance until the next weapon is drawn. (1 Min Cooldown)\nSell Price:" }
entries[212450] = { ["name"] = "Swarmlord's Authority", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,001 Haste\nEquip: Your attacks and abilities have a high chance to summon a scarab that retrieves a fortifying chunk of flesh from your target. Scarabs deal 6915 Physical damage and reduce your damage taken by 50% until 172816 damage has been prevented.\nUse: Send your swarm into a frenzy, summoning 12 scarabs over 3 sec to ravage your foes. The number of scarabs is increased by your Haste. (1 Min Cooldown)\nSell Price:" }
entries[212451] = { ["name"] = "Aberrant Spellforge", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+1,914 Intellect\nEquip: Accumulate dark power from the Spellforge every 15 sec to empower your next [specialization spell] to deal ( 1 * 73672 ) additional Shadow damage.\nUse: Recklessly intensify the power of the Spellforge, multiplying its current damage by 125% until shortly after leaving combat, up to 5 times. At full power, gain 830 Haste for 6 sec when empowering your [specialization spell].\n\nBeware glimpses of the Unseeming. (1 Min Cooldown)\nSell Price:" }
entries[212452] = { ["name"] = "Gruesome Syringe", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,001 Critical Strike\nEquip: Your healing spells have a high chance to cause you to inject yourself with a charge of Volatile Serum . Multiple charges may overlap.\n\nIf an ally drops below 70% health, expel a charge to heal them for 240979 . If unconsumed after 15 sec, charges catalyze to grant you 2894 Intellect for 10 sec instead.\nSell Price:" }
entries[212453] = { ["name"] = "Skyterror's Corrosive Organ", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+1,914 Strength\nUse: Spray your target with volatile acid, dealing ( 1 * 7902 ) Nature damage every 1 sec for 20 sec.\n\nYour abilities intensify the acid's damage by an additional ( 1 * 7902 ) per sec for the remaining duration and splash up to 5 nearby enemies for ( 1 * 790 ) Nature damage per stack. (1s cooldown) (2 Min Cooldown)\nSell Price:" }
entries[212454] = { ["name"] = "Mad Queen's Mandate", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,001 Critical Strike\nUse: Take what is rightfully yours, gorging on your target's essence to deal ( 1 * 2174283 ) Shadow damage and healing you for 320973 over 2 sec. Damage and healing increased based on the target's missing health.\n\nCooldown reduced by 60 sec if this effect kills the target. (2 Min Cooldown)\nSell Price:" }
entries[212455] = { ["name"] = "11.0 Raid Template - Physical DPS - Trinket", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 [Agility or Strength]\nSell Price:" }
entries[212456] = { ["name"] = "Void Reaper's Contract", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+1,914 Agility\nEquip: Your abilities have a high chance to summon a phantom ethereal, dealing ( 1 * 159051 ) Shadow damage to your target and [source value] Shadow damage to all other enemies caught in its path.\n\nIf the target is below 35% health, this effect summons two additional phantoms at 25% effectiveness. (1s cooldown)\n\nKy'veza's Cruel Implements (0/2)\nVoid Reaper's Warp Blade\nVoid Reaper's Contract\n(2) Set : Void Reaper's Contract always summons additional phantoms against enemies afflicted by Queensbane.\nSell Price:", ["unresolvedValues"] = true }
