entries[212491] = { ["name"] = "Sweet Eclipse", ["text"] = "Binds when picked up\nUnique (100)\nUse: Restores ( 80357 / 5 * 20) health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and and gain the Sweet Eclipse buff, allowing you to increase Crit Chance 3% for each enemy killed when fighting in the shadows.\n\nUsable in Light's Blooming and nearby keyflame areas." }
entries[212492] = { ["name"] = "Twilight-Spiced Grouper", ["text"] = "Binds when picked up\nUnique (100)\nUse: Restores ( 80357 / 5 * 20) health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become Well Fed, increase movement speed by 15%, and gain water walking while in Light's Blooming and nearby keyflame areas.\n\nUsable in Light's Blooming and nearby keyflame areas." }
