entries[212599] = { ["name"] = "Noble Flying Carpet", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses a Noble Flying Carpet. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Mages celebrating Noblegarden turned their ordinary festive decor into floating spectacles, only to have them stolen by an angry druid.\"\nDrop:\nDaetan Swiftplume\nHoliday:\nNoblegarden" }
