entries[212645] = { ["name"] = "Clayscale Hornstrider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Named for their dusty-red appearance, clayscale hornstriders can be found tearing across the muddy hills of the Ohn'ahran Plains.\"\nDrop:\nAzerothian Archives" }
