entries[212682] = { ["name"] = "Water's Beating Heart", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 Intellect\nEquip: Periodically imbue yourself while in combat with tainted Primal Wellspring water reducing your Versatility by 38 and movement speed by 10% for 15 sec.\nDispelling the water's impurities reverse the effect, increasing your Versatility by 161 , movement speed by 10% and granting all nearby allies a 1087 shield for 15 sec.\n\"When held the curio slowly pulses, as water begins enveloping and tightening around your heart, slowing your heartbeat.\"\nSell Price:" }
entries[212683] = { ["name"] = "Globe of Jagged Ice", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 Agility\nUse: Imbue your abilities with the globe's powers gaining 50 charges of Frozen Wellspring. Dealing damage consumes a charge dealing 42 additional Frost damage and apply Wellspring's Frost, slowing enemy movement speed by 2% per stack.\n\nWhen Frozen Wellspring is fully consumed shatter all targets afflicted with Wellspring's Frost dealing 141 Frost damage per stack split between all nearby targets. (2 Min Cooldown)\nSell Price:" }
entries[212684] = { ["name"] = "Umbrelskul's Fractured Heart", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 Intellect\nEquip: Your harmful spells and abilities have a low chance to call upon tragic arcane powers to infect your target with Crystal Sickness, dealing [source value] Arcane damage over 10 sec, increasing every second.\n\nCreatures, other than players and bosses, who drop below 5% health while afflicted will crystallize, die and infect a nearby enemy with Crystal Sickness. This can happen up to 3 times.\nSell Price:", ["unresolvedValues"] = true }
entries[212685] = { ["name"] = "Tome of Unstable Power", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 Intellect\nEquip: Your harmful spells have a chance to create 1 to 3 Arcane Illusions of yourself that channel for 3 sec before unleashing Arcane Barrage at your target's location dealing up to ( 2487 * 1.1) Arcane damage to all enemies in the area.\nSell Price:" }
