entries[212751] = { ["name"] = "Algari Potion Cauldron", ["text"] = "Binds to Warband\nUse: Place a cauldron that allows party and raid members to take potions of their choosing from among the recipes known by your Warband. Only alchemists with the cauldron recipe will contribute.\n\nThe cauldron lasts for 5 min and has 80 charges. Each charge grants 5 potions. You will receive the Crystalforged Cauldron back once used.\nSell Price:" }
entries[212752] = { ["name"] = "Algari Potion Cauldron", ["text"] = "Binds to Warband\nUse: Place a cauldron that allows party and raid members to take potions of their choosing from among the recipes known by your Warband. Only alchemists with the cauldron recipe will contribute.\n\nThe cauldron lasts for 5 min and has 80 charges. Each charge grants 5 potions. You will receive the Crystalforged Cauldron back once used.\nSell Price:" }
