entries[212754] = { ["name"] = "Crystalforged Cauldron", ["text"] = "Binds to Warband\nCrafting Reagent\n\"Durable enough to handle the most corrosive concoctions. Can be purchased from alchemy and blacksmithing suppliers on Khaz Algar for use in flask and potion cauldrons.\"\nSell Price:" }
entries[212755] = { ["name"] = "Remnant Satchel", ["text"] = "Quest Item\nUnique (200)\n\"A satchel full of Radiant Remnants.\"" }
entries[212756] = { ["name"] = "Inexorable Resonator", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Strength]\nEquip: Falling below 75% health activates the defense matrix for up to 15 sec, absorbing 50% of damage taken up to a maximum of 16069 . While the matrix holds, the resonator pulses every 1 sec to deal 177 Fire damage to all nearby enemies. Damage is reduced beyond 8 enemies.\n\nThis may only occur once every 1.5 min.\nSell Price:" }
entries[212757] = { ["name"] = "Granyth's Enduring Scale", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Strength]\nUse: Reduce damage taken by 75% for 20 sec or until 22723 damage has been absorbed. Your Armor is increased by 179 while the shield holds, further increasing by 9 when struck, stacking up to 20 times. The shield explodes when broken, dealing 4970 Physical damage split between all nearby enemies.\n\nDamage increased per enemy struck, up to 5. (100ms cooldown) (2 Min Cooldown)\nSell Price:" }
entries[212758] = { ["name"] = "Incendiary Terror", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Your abilities have a chance to inflict additional Fire damage and horrify your enemy for 3 sec.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[212759] = { ["name"] = "Meteor Storm", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Your abilities have a chance to conjure a hail of meteors, inflicting Fire damage to nearby enemies and stunning them for 3 sec.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[212760] = { ["name"] = "Wildfire", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Your attacks have a chance to inflict Fire damage and spread Wildfire to a nearby enemy inflicting Fire damage every 1 sec for 10 sec.\n\nWildfire stacks and spreads to nearby enemies, stacking up to 3 times.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[212761] = { ["name"] = "Pouch of Coins", ["text"] = "\"Someone must have hidden these for safekeeping long, long ago.\"\nSell Price:" }
entries[212762] = { ["name"] = "Tarnished Horn Signet", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"It seems the dracthyr got the idea for horn jewelry from the dragonkin who lived here before them.\"\nSell Price:" }
entries[212763] = { ["name"] = "Spoiled Honeywine", ["text"] = "\"The liquid in this bottle is cloudy and dull. While not good for drinking, it may be worth studying.\"\nSell Price:" }
entries[212764] = { ["name"] = "Fishing Net Fragment", ["text"] = "\"This bit of net was torn and repaired dozens of times before finally being stowed away.\"\nSell Price:" }
entries[212765] = { ["name"] = "Fish Bones", ["text"] = "\"Covered in marks from draconic teeth, as if someone had enjoyed every last bite.\"\nSell Price:" }
entries[212766] = { ["name"] = "Amphora Fragment", ["text"] = "\"If you look closely, you can see clawed thumbprints preserved in the clay.\"\nSell Price:" }
entries[212767] = { ["name"] = "Broken Beaker", ["text"] = "\"The neck has been broken off this beaker, so that it may better serve as a drinking vessel.\"\nSell Price:" }
entries[212768] = { ["name"] = "Niffen-Sized Dagger", ["text"] = "\"This dagger is the perfect shape to be held in wide, clawed hands.\"\nSell Price:" }
entries[212769] = { ["name"] = "Tattered Wanted Poster", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"The print has been rendered illegible, but someone has made rude drawings over the picture.\"\nSell Price:" }
entries[212770] = { ["name"] = "Smashed Pottery", ["text"] = "\"Rather than worn by time, this appears to have been smashed by throwing knives.\"\nSell Price:" }
entries[212771] = { ["name"] = "Charred Snail Shells", ["text"] = "\"The remnants of herbs suggest these made a hearty fire-roasted meal.\"\nSell Price:" }
entries[212772] = { ["name"] = "False Silver Coin", ["text"] = "\"Who could say if this bent coin was part of a trick, or looted by a disappointed bandit?\"\nSell Price:" }
entries[212773] = { ["name"] = "Rusted Locket", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Was this stolen, or were the bandits sentimental? Either way, the inside is inaccessible.\"\nSell Price:" }
entries[212774] = { ["name"] = "Sharpened Shalewing Bones", ["text"] = "\"The wear on these sharpened bones suggest they were used as toothpicks.\"\nSell Price:" }
