entries[212976] = { ["name"] = "Drakonid Duck Carving", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Nothing expresses the technological advancements of a civilization more than their ability to accurately recreate a duck.\"\nSell Price:" }
entries[212977] = { ["name"] = "Drakonid Sign Placard", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"While the words themselves are lost with time, the very presence of a sign implies a system of writing and civilization dating back countless generations.\"\nSell Price:" }
entries[212978] = { ["name"] = "Dragon Painter's Palette", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Anyone can slather colors on a canvas, but the presence of a palette shows a level of deliberate intention that tickles an archivist's imagination.\"\nSell Price:" }
