entries[213001] = { ["name"] = "Clump of Ore", ["text"] = "Quest Item\nRequires level 70 to 73 ( 73)\n\"This clump of unrefined ore protrudes from the earth. It is cold to the touch and surprisingly light in weight.\"" }
