entries[213020] = { ["name"] = "Ancient Drakonid Shovel", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Through careful scrutiny, it can be determined the date of this shovel's creation. More importantly, that will reveal when agriculture was introduced.\"\nSell Price:" }
entries[213021] = { ["name"] = "Corked Drakonid Vial", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"The cork seems to have fused with the bottle over an eternity of decay. There's as much to be learned from opening it as there is from not.\"\nSell Price:" }
entries[213022] = { ["name"] = "Drakonid Blacksmith Hammer", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"While almost impossible to determine the age of this particular hammer, the materials used to forge it can reveal much of the civilization's technology.\"\nSell Price:" }
entries[213023] = { ["name"] = "Oil-Drenched Djaradin Torch", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Once the djaradin discovered oil, there was nothing they wouldn't use it in. Fires, weapons, recreation, all were impacted by this new discovery.\"\nSell Price:" }
entries[213024] = { ["name"] = "Bloody Djaradin Mug", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Little is known about the djaradin's specific culture, but one has to come to certain conclusions when they discover mugs stained in blood.\"\nSell Price:" }
entries[213025] = { ["name"] = "Ancient Djaradin Bolt", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"As cruel a century ago as they are today, djaradin weapons have advanced little since their rise to power.\"\nSell Price:" }
entries[213026] = { ["name"] = "Massive Drakonid Brush", ["text"] = "\"Large drakonkin wield these brushes with surprising dexterity, from painting homes to intricate murals.\"\nSell Price:" }
entries[213027] = { ["name"] = "Chipped Drakonid Cup", ["text"] = "\"Worth a small fortune in its heyday, this poorly preserved chalice will fetch only a meager price at a local vendor.\"\nSell Price:" }
entries[213028] = { ["name"] = "Cracked Drafting Compass", ["text"] = "\"Used to create vast archives of maps and sea charts, finding a compass is only the first step in discovering an ancient civilization's technological prowess.\"\nSell Price:" }
entries[213029] = { ["name"] = "Bent Drakonid Fork", ["text"] = "\"A drakonid fork may seem mundane to the untrained eye, but this tool belies the sophistication of its manufacturer.\"\nSell Price:" }
entries[213030] = { ["name"] = "Rusty Garden Shears", ["text"] = "\"A small dot of blood marking the tip of the shears may explain why a frustrated gardener discarded this tool long ago.\"\nSell Price:" }
entries[213031] = { ["name"] = "Misshapen Drakonid Goblet", ["text"] = "\"The years have done their damage to this goblet, but a keen eye can still learn much from the remains.\"\nSell Price:" }
entries[213032] = { ["name"] = "Warped Drakonid Jar", ["text"] = "\"The accompanying lid no longer fits the jar, but now can be used as a tiny saucer.\"\nSell Price:" }
entries[213033] = { ["name"] = "Brittle Blacksmith Tongs", ["text"] = "\"This battlescarred pair of tongs have stoked fires for centuries. Tiny imperfections and knicks in the metal reveal much of what they handled.\"\nSell Price:" }
entries[213034] = { ["name"] = "Cracked Drakonid Bowl", ["text"] = "\"Unsuitable for practical use, this lovely bowl would make an excellent centerpiece in any archaeologist's gallery.\"\nSell Price:" }
entries[213035] = { ["name"] = "Crusty Dracthyr Brush", ["text"] = "\"Caked in a myriade of dried paints, this brush is a treasure trove of specimen samples from various pigments and solutions.\"\nSell Price:" }
entries[213037] = { ["name"] = "Jagged Garden Trowel", ["text"] = "\"Years of use have seen this trowel become damaged beyond repair. Oh the stories it could tell.\"\nSell Price:" }
entries[213038] = { ["name"] = "Cracked Magnifying Glass", ["text"] = "\"This may have been helpful for reading the fine print in Neltharion's plans for the dracthyr.\"\nSell Price:" }
entries[213039] = { ["name"] = "Thin Drakonid Spoon", ["text"] = "\"Everything from utensils to cutlery serve to tell the stories of the local people in their day to day lives.\"\nSell Price:" }
entries[213040] = { ["name"] = "Tarnished Djaradin Amulet", ["text"] = "\"Weathering has rendered much of the intricacies of this amulet indecipherable, but the general shape may shed some light on djaradin customs.\"\nSell Price:" }
entries[213041] = { ["name"] = "Desiccated Djaradin Scroll", ["text"] = "\"After painstakingly collecting enough scraps to piece together this rare find, it turns out that this scroll is covered in meaningless doodles.\"\nSell Price:" }
entries[213042] = { ["name"] = "Deteriorated Djaradin Banner", ["text"] = "\"Flown during peacetime and war, a djaradin banner shows its age through the rips and tears it endures over a long life.\"\nSell Price:" }
entries[213043] = { ["name"] = "Brittle Djaradin Leather", ["text"] = "\"Hardly useful for crafting anymore, this leather comes from an unidentifiable source that is better left to the imagination.\"\nSell Price:" }
entries[213044] = { ["name"] = "Frayed Fang Amulet", ["text"] = "\"Upon closer inspection, the fang for this amulet appears to be from a djaradin. Perhaps a battle trophy?\"\nSell Price:" }
entries[213045] = { ["name"] = "Snapped Djaradin Necklace", ["text"] = "\"Little can be learned from this broken amulet, as half of its pieces have gone missing throughout the years.\"\nSell Price:" }
entries[213062] = { ["name"] = "Paradise's Golden Axe", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Axe\n1 Damage Speed 2.60\n(0.4 damage per second)\n\"Though its bright hues are reminiscent of jungle birds' feathers, its edge does not tickle.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
